import fs from 'fs';

const ACME_UPSTREAM = process.env.ACME_CHALLENGE_UPSTREAM || 'http://host.docker.internal:8081';

export function writeAcmeHttpOnlyNginxConfig({ domain, acmeUpstream = ACME_UPSTREAM }) {
    return `
# Auto Generated By DeployHub (ACME challenge)
server {
    listen 80;
    server_name ${domain};
    location ^~ /.well-known/acme-challenge/ {
        proxy_pass ${acmeUpstream};
        proxy_set_header Host \\$host;
        proxy_set_header X-Real-IP \\$remote_addr;
        proxy_set_header X-Forwarded-For \\$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \\$scheme;
    }
    location / {
        return 200 'DeployHub SSL setup in progress';
        add_header Content-Type text/plain;
    }
}
`;
}

export function writeNginxConfig({
    domain,
    sslDomain,
    type = 'backend',
    target,
    staticPath,
    outputPath,
    letsencryptDir = '/etc/letsencrypt/live',
    acmeUpstream = ACME_UPSTREAM,
}) {
    let locationBlock = '';
    if (type === 'static') {
        locationBlock = `
    root ${staticPath};
    index index.html;
    location / {
        try_files $uri $uri/ /index.html;
    }`;
    } else {
        locationBlock = `
    location / {
        proxy_pass ${target};
        proxy_http_version 1.1;
        proxy_set_header Host \\$host;
        proxy_set_header X-Real-IP \\$remote_addr;
        proxy_set_header X-Forwarded-For \\$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header Upgrade \\$http_upgrade;
        proxy_set_header Connection \\$connection_upgrade;
        client_max_body_size 200M;
    }`;
    }
    const config = `
# Auto Generated By DeployHub
server {
    listen 80;
    server_name ${domain};
    location ^~ /.well-known/acme-challenge/ {
        proxy_pass ${acmeUpstream};
        proxy_set_header Host \\$host;
        proxy_set_header X-Real-IP \\$remote_addr;
        proxy_set_header X-Forwarded-For \\$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \\$scheme;
    }
    location / {
        return 301 https://\\$host\\$request_uri;
    }
}
server {
    listen 443 ssl;
    server_name ${domain};
    ssl_certificate ${letsencryptDir}/${sslDomain}/fullchain.pem;
    ssl_certificate_key ${letsencryptDir}/${sslDomain}/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
${locationBlock}
}
`;
    if (outputPath) {
        fs.writeFileSync(outputPath, config);
        return outputPath;
    }
    return config;
}
